import{_ as e}from"./chunks/09-login.Cp0oUy7l.js";import{_ as o,a as r,b as i}from"./chunks/13b-mobile-drawer.BiU5fk85.js";import{_ as a}from"./chunks/11-settings.B_GZgwvL.js";import{_ as s}from"./chunks/11b-settings-add-root.Dcjj_7UM.js";import{_ as n}from"./chunks/01-files-browse.Dr_PlV-Q.js";import{_ as d}from"./chunks/01c-files-reports.DZ25K_9T.js";import{_ as l}from"./chunks/12-audit.CWIaVMMc.js";import{_ as c}from"./chunks/07-health.CsoSZ-cX.js";import{_ as p,o as g,c as h,a2 as m}from"./chunks/framework.DUZafPzB.js";const F=JSON.parse('{"title":"First login & add roots","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-login.md","filePath":"guide/first-login.md","lastUpdated":1791394961000}'),f={name:"guide/first-login.md"};function b(u,t,_,w,A,x){return g(),h("div",null,[...t[0]||(t[0]=[m('<h1 id="first-login-add-roots" tabindex="-1">First login &amp; add roots <a class="header-anchor" href="#first-login-add-roots" aria-label="Permalink to &quot;First login &amp; add roots&quot;">​</a></h1><p>After Hub and Agent are running, finish in the browser: log in (with PoW) → select a machine → Add Root → start browsing.</p><h2 id="_1-open-the-login-page" tabindex="-1">1. Open the login page <a class="header-anchor" href="#_1-open-the-login-page" aria-label="Permalink to &quot;1. Open the login page&quot;">​</a></h2><p>Visit the Hub URL. The login page includes:</p><ul><li>Username / Password</li><li><strong>Verification (PoW)</strong>: solves a challenge in the background — Solving… → <strong>Ready</strong></li><li>Keep me signed in 30 days (optional)</li><li><strong>Continue</strong></li></ul><p><img src="'+e+'" alt="Sign in: PoW Ready"></p><p><img src="'+o+'" alt="Credentials filled"></p><p>Production accounts come from <code>--init-config</code>. Development mode defaults to <code>admin</code> / <code>dev-password</code>.</p><p>If Verification fails or you are rate-limited, click the refresh icon to fetch a new challenge and try again later.</p><h2 id="_2-select-an-agent" tabindex="-1">2. Select an Agent <a class="header-anchor" href="#_2-select-an-agent" aria-label="Permalink to &quot;2. Select an Agent&quot;">​</a></h2><p>After login, if no machine is selected the main area prompts <strong>Select an agent</strong>. Click the target under sidebar <strong>Agents</strong> (Online, latency, root count).</p><p>Once selected, the sidebar shows <strong>Workspace</strong> navigation: Files, Explorer, Collections, Transfer, Terminal, Search, Settings, System; plus <strong>Hub → Audit</strong>.</p><h2 id="_3-settings-→-add-root" tabindex="-1">3. Settings → Add Root <a class="header-anchor" href="#_3-settings-→-add-root" aria-label="Permalink to &quot;3. Settings → Add Root&quot;">​</a></h2><p>Open <strong>Settings</strong>:</p><ol><li>Confirm the Connection card: Online, Round-trip, Enabled roots.</li><li>Under <strong>Workspace roots → Add root</strong>, fill in: <ul><li><strong>NAME</strong>: short label in the sidebar / address bar (e.g. <code>demo</code>, <code>projects</code>)</li><li><strong>PATH ON AGENT</strong>: absolute path on the Agent host, or <code>~/…</code></li></ul></li><li>Click <strong>Add root</strong>. Overly broad paths (e.g. <code>/</code> or home root) ask for explicit confirmation.</li></ol><p><img src="'+a+'" alt="Settings overview"></p><p><img src="'+s+'" alt="Add root form"></p><p>Invalid paths are rejected and <strong>do not</strong> corrupt existing config. Roots, pins, and collections live in Agent state and persist with the Agent identity.</p><h2 id="_4-browse-in-files" tabindex="-1">4. Browse in Files <a class="header-anchor" href="#_4-browse-in-files" aria-label="Permalink to &quot;4. Browse in Files&quot;">​</a></h2><p>Go back to <strong>Files</strong>, switch roots with the dropdown, enter directories, and click a file to preview on the right.</p><p><img src="'+n+'" alt="Files root listing"></p><p><img src="'+d+'" alt="reports directory (long names)"></p><h2 id="sidebar-views" tabindex="-1">Sidebar views <a class="header-anchor" href="#sidebar-views" aria-label="Permalink to &quot;Sidebar views&quot;">​</a></h2><table tabindex="0"><thead><tr><th>View</th><th>Role</th><th>Docs</th></tr></thead><tbody><tr><td>Files</td><td>Breadcrumb + list browse, multi-tab preview</td><td><a href="/filebox/features/browse">Browse files</a></td></tr><tr><td>Explorer</td><td>Tree-style browse</td><td><a href="/filebox/features/explorer">Explorer</a></td></tr><tr><td>Search</td><td>Workspace filename / content search (desktop float / mobile sheet)</td><td><a href="/filebox/features/search">Search</a></td></tr><tr><td>Collections</td><td>Virtual file groups across directories</td><td><a href="/filebox/features/collections">Collections</a></td></tr><tr><td>Transfer</td><td>The only writable scratch upload folder</td><td><a href="/filebox/features/transfer">Transfer</a></td></tr><tr><td>Terminal</td><td>Optional TOTP-gated remote shell</td><td><a href="/filebox/features/terminal">Terminal</a></td></tr><tr><td>Settings</td><td>Manage roots, Office preview toggle</td><td>This page</td></tr><tr><td>System</td><td>CPU / memory / processes</td><td><a href="/filebox/features/stats">System monitor</a></td></tr><tr><td>Audit</td><td>Login audit (no selected Agent required)</td><td><a href="/filebox/ops/hub">Hub ops</a></td></tr><tr><td>Version</td><td>Click for About / Diagnostics</td><td>—</td></tr></tbody></table><p><img src="'+l+'" alt="Audit"></p><p><img src="'+c+'" alt="About / Diagnostics"></p><h2 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h2><p>Below ~768px viewport width the sidebar becomes a drawer; list and preview swap full-screen. The top bar has menu and Search entries.</p><p><img src="'+r+'" alt="Mobile Files"></p><p><img src="'+i+'" alt="Mobile sidebar drawer"></p><p>Common issues: <a href="/filebox/ops/faq">FAQ</a>.</p>',31)])])}const R=p(f,[["render",b]]);export{F as __pageData,R as default};
